function marquee() {
  document.querySelectorAll(".marquee-container").forEach((e) => {
    let t = e.querySelector(".marquee-content");
    var o = [...e.querySelectorAll(".marquee-item")],
      r = parseFloat(e.getAttribute("data-speed")) || 50,
      n =
        ((t.innerHTML = ""),
        o.forEach((e) => t.appendChild(e.cloneNode(!0))),
        [...t.children]);
    let i = 0;
    n.forEach((e) => (i += e.offsetWidth));
    var o = e.offsetWidth,
      s = Math.ceil(o / i) + 2;
    for (let e = 0; e < s; e++)
      n.forEach((e) => {
        t.appendChild(e.cloneNode(!0));
      });
    let a = 0,
      c =
        ([...t.children].forEach((e) => (a += e.offsetWidth)),
        gsap.set(t, { x: 0, willChange: "transform", force3D: !0 }),
        gsap.timeline({ repeat: -1 }));
    c.to(t, {
      x: -a,
      duration: a / r,
      ease: "none",
      modifiers: { x: (e) => (parseFloat(e) % a) + "px" }
    }),
      (!parseFloat(e.getAttribute("hover-pause")) && 1) ||
        (e.addEventListener("mouseenter", () => c.pause()),
        e.addEventListener("mouseleave", () => c.resume()));
  });
}
function customDropdown() {
  let e = document.querySelectorAll(
    ".dropdown-custom, .dropdown-custom-select"
  );
  function c(r) {
    e.forEach((e) => {
      var t = e.querySelector(".dropdown-custom-menu"),
        o = e.querySelector(".dropdown-custom-btn");
      (r && e === r) ||
        (t.classList.remove("dropdown--active"),
        o.classList.remove("--active"));
    });
  }
  e.forEach((n) => {
    let t = n.querySelector(".dropdown-custom-btn"),
      o = n.querySelector(".dropdown-custom-menu");
    var e = n.querySelectorAll(".dropdown-custom-item");
    let i = n.querySelector(".value-select"),
      s = n.querySelector(".dropdown-custom-text"),
      a = n.classList.contains("dropdown-custom-select");
    t.addEventListener("click", function (e) {
      e.stopPropagation(),
        c(n),
        o.classList.toggle("dropdown--active"),
        t.classList.toggle("--active");
    }),
      document.addEventListener("click", function () {
        c();
      }),
      e.forEach((r) => {
        r.addEventListener("click", function (e) {
          var t, o;
          e.stopPropagation(),
            a
              ? ((e = r.textContent),
                (s.textContent = e),
                n.classList.add("selected"))
              : ((e = (e = i.querySelector("img")) ? e.src : ""),
                (t = i.querySelector("span").textContent),
                (o = r.innerHTML),
                (i.innerHTML = o),
                "Time" !== t.trim() &&
                  (r.innerHTML = e
                    ? `<span>${t}</span><img src="${e}" alt="" />`
                    : `<span>${t}</span>`)),
            c();
        });
      }),
      window.addEventListener("scroll", function () {
        o.closest(".header-lang") &&
          (o.classList.remove("dropdown--active"),
          t.classList.remove("--active"));
      });
  });
}
