function effectFade() {
  gsap.utils.toArray(".data-fade-in").forEach((e) => {
    gsap.fromTo(
      e,
      { "will-change": "opacity, transform", opacity: 0, y: 20 },
      {
        scrollTrigger: { trigger: e, start: "top 80%", end: "bottom 80%" },
        opacity: 1,
        y: 0,
        duration: 0.5,
        ease: "sine.out"
      }
    );
  });
}
function registerForm() {
  if (!($(".form-register-wrapper").length < 1)) {
    let r = $(".form-register-wrapper form");
    r.on("submit", function (e) {
      e.preventDefault();
      var e = {
          name: r.find("input[name='name']"),
          phone: r.find("input[name='phonenumber']"),
          email: r.find("input[name='email']"),
          course: r.find(".dropdown-custom-text")
        },
        t = r.find("textarea");
      r.find(".error-message").remove(), r.find(".error").removeClass("error");
      let o = !0;
      $.each(e, (e, t) => {
        ("course" === e ? t.text() : t.val()).trim() ||
          (t.addClass("error"), (o = !1));
      }),
        o &&
          $.ajax({
            type: "POST",
            url: ajaxUrl,
            data: {
              action: "form_register_course",
              name: e.name.val().trim(),
              phone: e.phone.val().trim(),
              email: e.email.val().trim(),
              course: e.course.text().trim(),
              message: t.val().trim()
            },
            beforeSend: function () {
              r.find("button[type='submit']").addClass("aloading");
            },
            success: function (e) {
              r.find("button[type='submit']").removeClass("aloading");
              var t = document.getElementById("modalBookingSuccess");
              bootstrap.Modal.getOrCreateInstance(t).show(), r[0].reset();
            },
            error: function (e, t, o) {
              console.error("Lỗi khi gửi form:", o);
            }
          });
    });
  }
}
